// ============================================
// DPoP JWT Generator using RS256
// ============================================

const jsrsasignUrl = "https://kjur.github.io/jsrsasign/jsrsasign-all-min.js";

// Load library (cached in globals for performance)
if (!pm.globals.has("jsrsasign_cached")) {
    console.log("Loading jsrsasign library...");
    pm.sendRequest(jsrsasignUrl, function (err, res) {
        if (err) {
            console.error("Failed to load jsrsasign:", err);
            throw new Error("Cannot load jsrsasign library");
        }
        pm.globals.set("jsrsasign_cached", res.text());
        console.log("Library loaded successfully");
        generateDpopJwt();
    });
} else {
    generateDpopJwt();
}

function generateDpopJwt() {
    // Execute the cached library
    eval(pm.globals.get("jsrsasign_cached"));

    // -----------------------------------------
    // 1. Generate RSA Key Pair (2048-bit)
    // -----------------------------------------

    if (!pm.environment.has("_dpop_privatekey")){
        console.log("Generating RSA key pair...");
        const keypair = KEYUTIL.generateKeypair("RSA", 2048);
        const privateKey = keypair.prvKeyObj;
        const publicKey = keypair.pubKeyObj;

        // -----------------------------------------
        // 2. Export keys in required formats
        // -----------------------------------------
        // Private key in PEM format
        const privatePem = KEYUTIL.getPEM(privateKey, "PKCS8PRV");

        // Public key in JWK format
        const publicJwk = KEYUTIL.getJWKFromKey(publicKey);

        pm.environment.set("_dpop_privatekey", privatePem);
        pm.environment.set("_dpop_pubkey", JSON.stringify(publicJwk));   
    }

    // Private key in PEM format
    const privatePem = pm.environment.get("_dpop_privatekey")
    // Public key in JWK format
    const publicJwk = JSON.parse(pm.environment.get("_dpop_pubkey"));

    // Add required JWK fields for DPoP
    publicJwk.use = "sig";
    publicJwk.alg = "RS256";

    // -----------------------------------------
    // 3. Store keys in environment variables
    // -----------------------------------------

    // jwtAudience = pm.environment.get("jwt-audience");
    jwtAudience = pm.environment.get('url') + '/oauth2/' + pm.environment.get('agent-authZ-server-ID') + '/v1/token';

    // -----------------------------------------
    // 4. Build DPoP JWT
    // -----------------------------------------
    // Generate unique JWT ID
    const jti = KJUR.crypto.Util.getRandomHexOfNbytes(16);

    // Timestamps
    const now = Math.floor(Date.now() / 1000);

    // JWT Header
    const header = {
        alg: "RS256",
        typ: "dpop+jwt",
        jwk: publicJwk
    };

    // JWT Payload
    const payload = {
        jti: jti,
        htm: pm.request.method,
        htu: jwtAudience,
        iat: now,
        exp: now + 300  // 5 minutes expiry
    };

    // -----------------------------------------
    // 5. Sign the JWT
    // -----------------------------------------
    const signedJwt = KJUR.jws.JWS.sign(
        "RS256",
        JSON.stringify(header),
        JSON.stringify(payload),
        privatePem
    );

    // -----------------------------------------
    // 6. Store signed JWT
    // -----------------------------------------
    pm.environment.set("_dpop_opa-pub_signed_jwt", signedJwt);

    // // Log results
    // console.log("=== DPoP JWT Generated Successfully ===");
    // console.log("Algorithm: RS256");
    // console.log("JTI:", jti);
    // console.log("Method:", pm.request.method);
    // console.log("URI:", pm.request.url.toString().split('?')[0]);
    // console.log("JWT:", signedJwt);
}

